#include "stdlib/math/base/special/log10f.h"
#include "stdlib/number/float32/base/to_word.h"
#include "stdlib/number/float32/base/from_word.h"
#include "stdlib/constants/float64/high_word_abs_mask.h"
#include "stdlib/constants/float64/high_word_significand_mask.h"
#include "stdlib/constants/float32/exponent_bias.h"
#include "stdlib/constants/float32/ninf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/kernel_log1p.h"
#include <stdint.h>

static const double TWO25 = 3.3554432000e+07;     // 0x4c000000
static const double IVLN10HI = 4.3432617188e-01;  // 0x3ede6000
static const double IVLN10LO = -3.1689971365e-05;  // 0xb804ead9
static const double LOG10_2HI = 3.0102920532e-01; // 0x3e9a2080
static const double LOG10_2LO = 7.9034151668e-07; // 0x355427db

// 0x7f800000 = 2146435072 => 0 11111111111 00000000000000000000 => biased exponent: 2047 = 1023+1023 => 2^1023
static const int32_t HIGH_MAX_NORMAL_EXP = 0x7f800000;

// 0x00800000 = 1048576 => 0 00000000001 00000000000000000000 => biased exponent: 1 = -1022+1023 => 2^-1022
static const int32_t HIGH_MIN_NORMAL_EXP = 0x00800000;

// 0x3f800000 = 1072693248 => 0 01111111111 00000000000000000000 => biased exponent: 1023 = 0+1023 => 2^0 = 1
static const int32_t HIGH_BIASED_EXP_0 = 0x3f800000;

/**
* Evaluates the common logarithm (base ten) for single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_log10f( 4.0f );
* // returns ~0.602f
*/
float stdlib_base_log10f( const float x ) {
	uint32_t hx;
	int32_t ihx;
	float hfsq;
	float hi;
	int32_t i;
	int32_t k;
	float lo;
	float xc;
	float f;
	float R;
	float y;

	if ( stdlib_base_is_nan( x ) || x < 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	xc = x;
	stdlib_base_float32_to_word( xc, &hx );
	ihx = (int32_t)hx;
	k = 0;
	if ( ihx < HIGH_MIN_NORMAL_EXP ) {
		// Case: x < 2**-1022
		if ( ( ihx & STDLIB_CONSTANT_FLOAT64_HIGH_WORD_ABS_MASK ) ) {
			return STDLIB_CONSTANT_FLOAT32_NINF;
		}
		k -= 25;

		// Subnormal number, scale up x:
		xc *= TWO25;
		stdlib_base_float32_to_word( xc, &hx );
		ihx = (int32_t)hx;
	}
	if ( ihx >= HIGH_MAX_NORMAL_EXP ) {
		return xc + xc;
	}
	// Case: log(1) = +0
	if ( ihx == HIGH_BIASED_EXP_0 ) {
		return 0;
	}
	k += ( ( ihx >> 23 ) - STDLIB_CONSTANT_FLOAT32_EXPONENT_BIAS );
	ihx &= STDLIB_CONSTANT_FLOAT64_HIGH_WORD_SIGNIFICAND_MASK;
	i = ( ihx + 0x4afb0d ) & HIGH_MIN_NORMAL_EXP;

	// Normalize x or x/2...
	stdlib_base_float32_from_word( (uint32_t)( ihx | ( i ^ HIGH_BIASED_EXP_0 ) ), &xc );
	k += ( i >> 23 );
	y = (float)k;
	f = xc - 1.0;
	hfsq = 0.5 * f * f;
	R = stdlib_base_kernel_log1p( f );

	/* See e_log2f.c and e_log2.c for details. */
	if (sizeof(float_t) > sizeof(float))
		return (R - hfsq + f) * ((float_t)IVLN10LO + IVLN10HI) + y;

	hi = f - hfsq;
	stdlib_base_float32_to_word( hi, &hx );
	stdlib_base_float32_from_word( hx& STDLIB_CONSTANT_FLOAT64_HIGH_WORD_ABS_MASK, &hi );
	lo = ( f - hi ) - hfsq + R;
	return ( y * LOG10_2LO ) + ( ( lo + hi ) * IVLN10LO ) + ( lo * IVLN10HI ) + ( hi * IVLN10HI ) + ( y * LOG10_2HI );
}
